insert into public.blog_posts
  (title, restaurant_name, cuisine, city, area, halal_claim, rating, rating_source, source_name, source_url, summary, images, published_at, is_sample)
values
  ('Hyderabadi Zaiqa: a hallway-sized biryani room in Manhattan', 'Hyderabadi Zaiqa', 'Indian (Hyderabadi)', 'New York, NY', 'New York City', 'unsure', 5.0, '5 out of 5 stars in Time Out''s review; may be dated', 'Time Out New York', 'https://timeout.com/newyork/restaurants/hyderabadi-zaiqa',
   'Time Out gives this tiny Hell''s Kitchen spot a top score, built around a menu of 15 biryanis. The reviewer singles out the Hyderabadi goat dum biryani and the tangy goongura chicken biryani. Seating is minimal, and the restaurant has since opened a larger Murray Hill location.',
   '[{"url":"https://images.pexels.com/photos/4224304/pexels-photo-4224304.jpeg?auto=compress&cs=tinysrgb&w=1200","alt":"Stock photo of chicken biryani on a black plate","stock":true,"credit":"Pexels","credit_url":"https://www.pexels.com/photo/chicken-biryani-on-black-plate-4224304/"}]'::jsonb, '2026-10-16', false),
  ('Fasil Mediterranean brings Turkish plates to Boonton', 'Fasil Mediterranean Restaurant', 'Turkish / Mediterranean', 'Boonton, NJ', 'New Jersey', 'unsure', 4.6, '4.6 on OpenTable, about 363 reviews; may be dated', 'OpenTable', 'https://www.opentable.com.au/fasil-mediterranean-restaurant',
   'Diners on OpenTable praise the hummus, stuffed grape leaves and the chicken kebab plate, along with friendly service. The listing is categorised as Turkish, Mediterranean and Halal, with a mid-range price. Confirm halal practices with the restaurant directly.',
   '[{"url":"https://images.pexels.com/photos/19702493/pexels-photo-19702493.jpeg?auto=compress&cs=tinysrgb&w=1200","alt":"Stock photo of stuffed grape leaves on a wooden plate","stock":true,"credit":"Pexels","credit_url":"https://www.pexels.com/photo/side-view-of-stuffed-wine-leaves-on-a-wooden-plate-19702493/"}]'::jsonb, '2026-10-16', false),
  ('Shadman: Pakistani-Indian staples and a weekday buffet in Jersey City', 'Shadman Restaurant', 'Pakistani / Indian', 'Jersey City, NJ', 'New Jersey', 'unsure', null, '7.0 out of 10 on Foursquare, 59 ratings; may be dated', 'Visit Hudson', 'https://www.visithudson.org/things-to-do/restaurants/shadman-restaurant/',
   'A fast-casual Grove Street spot serving Pakistani and Indian food since 1991. Reviewers mention chicken tikka masala, naan and biryani, and a weekday lunch buffet is a draw. Opinions on consistency are mixed and listed hours conflict between sources, so check before you go.',
   '[{"url":"https://images.pexels.com/photos/20446413/pexels-photo-20446413.jpeg?auto=compress&cs=tinysrgb&w=1200","alt":"Stock photo of Indian naan bread","stock":true,"credit":"Pexels","credit_url":"https://www.pexels.com/photo/indian-naan-bread-with-additions-20446413/"}]'::jsonb, '2026-10-16', false);
